'use strict';
const PATHS=[
{id:'F',name:'AI & safe mining foundations',short:'Foundation',hours:60,desc:'Understand the mining journey, make sense of data and check AI before you act.',role:'Start here · all learners',lab:'AI evidence lab'},
{id:'G',name:'Exploration & geospatial skills',short:'Exploration',hours:180,desc:'Read maps, evaluate targets and preserve the evidence behind every sample.',role:'Field & geological support',lab:'Exploration decision lab'},
{id:'M',name:'Mining operations & equipment',short:'Operations',hours:180,desc:'Recognise critical hazards, respond to defects and hand over a safe shift.',role:'Operations support',lab:'Safe-shift decision lab'},
{id:'P',name:'Processing & laboratory skills',short:'Processing',hours:180,desc:'Follow material through a plant, calculate recovery and check laboratory quality.',role:'Plant & laboratory support',lab:'Processing & tank lab'},
{id:'L',name:'Logistics & infrastructure',short:'Logistics',hours:180,desc:'Plan feasible deliveries, track materials and recognise infrastructure constraints.',role:'Logistics & technical support',lab:'Dispatch planning lab'},
{id:'E',name:'Environment & community',short:'Environment',hours:180,desc:'Interpret monitoring, protect records and respond respectfully to community concerns.',role:'Environmental & community support',lab:'Rain-event investigation lab'}];
const KEY='mining-learning-lab-v1';
let state={version:1,notes:{},videoNotes:{},quiz:{},completed:[],labs:{},capstones:{},last:'F1'};
let storageOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.version===1)state=validateState(s);}catch(e){storageOK=false;}
function validateState(s){
 const out={version:1,notes:{},videoNotes:{},quiz:{},completed:[],labs:{},capstones:{},last:'F1'};
 const ids=BASE.modules.map(m=>m.id);
 for(const id of ids){if(s.videoNotes&&typeof s.videoNotes[id]==='string')out.videoNotes[id]=s.videoNotes[id].slice(0,30000);if(s.notes&&typeof s.notes[id]==='string')out.notes[id]=s.notes[id].slice(0,30000);if(s.quiz&&s.quiz[id]&&Array.isArray(s.quiz[id].answers)){const a=s.quiz[id].answers.slice(0,3).map(x=>Number.isInteger(x)&&x>=0&&x<3?x:-1);out.quiz[id]={answers:a,score:a.reduce((n,v,i)=>n+(v===LESSONS[id].quiz[i][2]),0)};}}
 out.completed=Array.isArray(s.completed)?[...new Set(s.completed.filter(id=>ids.includes(id)&&out.quiz[id]?.score===3&&(out.notes[id]||'').trim().length>=80))]:[];
 for(const p of PATHS){if(s.labs&&typeof s.labs[p.id]==='string')out.labs[p.id]=s.labs[p.id].slice(0,30000);if(s.capstones&&typeof s.capstones[p.id]==='string')out.capstones[p.id]=s.capstones[p.id].slice(0,50000);}
 if(ids.includes(s.last))out.last=s.last;return out;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;document.getElementById('save-status').textContent='Saved in this browser';}catch(e){storageOK=false;document.getElementById('save-status').textContent='Not saved · export your work';}updateProgress();}
function updateProgress(){document.getElementById('progress-count').textContent=state.completed.length+' / 30';document.getElementById('progress').value=state.completed.length;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function inline(s){return esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>');}
function md(s){const lines=s.split('\n');let out='',table=[];function flush(){if(table.length){out+='<div class="table-wrap"><table><thead><tr>'+table[0].map(c=>'<th>'+inline(c)+'</th>').join('')+'</tr></thead><tbody>'+table.slice(1).filter(r=>!r.every(c=>/^[-: ]+$/.test(c))).map(r=>'<tr>'+r.map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';table=[];}}for(const l of lines){if(l.trim().startsWith('|')){table.push(l.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim()));continue;}flush();if(l.startsWith('### '))out+='<h3>'+inline(l.slice(4))+'</h3>';else if(l.trim())out+='<p>'+inline(l)+'</p>';}flush();return '<div class="markdown">'+out+'</div>';}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4000);}
const navItems=[['landing','↗','About this training'],['account','◉','My access'],['home','⌂','Learning dashboard'],['courses','▤','Course pathways'],['labs','◇','Practice labs'],['videos','▷','Topic videos'],['nigeria','◆','Nigeria in focus'],['career','★','Career launch'],['simplan','◎','Simulation & VR plan'],['resources','↗','Simulation providers'],['workbook','▣','My workbook'],['assessment','✓','Final projects'],['guide','ⓘ','Course guide']];
function nav(active){document.getElementById('nav').innerHTML=navItems.map(([id,icon,label])=>`<a href="#${id}" ${active===id?'class="active" aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');document.getElementById('crumb').textContent=navItems.find(x=>x[0]===active)?.[2]||'Course pathways';}
function drawing(type,hero=false){
 const colors={a:'#c4d9bd',b:'#7c9e83',c:'#35624d',d:'#e8b84e'};
 let shapes='';
 if(type==='G'||hero)shapes=`<path d="M0 178 L95 76 168 133 255 38 400 166 520 120 600 190 V270 H0Z" fill="#2b5a48"/><path d="M0 202 L110 127 200 180 300 100 430 206 530 170 600 220 V270 H0Z" fill="#527a5c"/><path d="M0 235 L120 194 235 228 353 165 460 230 600 201 V270 H0Z" fill="#98af80"/><path d="M30 245 Q110 160 210 211 T390 213 T570 220" stroke="#e8b84e" stroke-width="4" fill="none" stroke-dasharray="8 6"/><circle cx="300" cy="100" r="14" fill="#e8b84e"/><circle cx="300" cy="100" r="5" fill="#123f35"/><path d="M300 80V45M280 100H255M320 100H345" stroke="#e8b84e" stroke-width="2"/><circle cx="110" cy="196" r="6" fill="#e8b84e"/><circle cx="460" cy="222" r="6" fill="#e8b84e"/>`;
 if(type==='F')shapes=`<rect x="55" y="40" width="210" height="150" rx="12" fill="#c4d9bd"/><rect x="80" y="65" width="160" height="95" rx="6" fill="#35624d"/><path d="M95 135L125 120 155 130 185 90 220 80" fill="none" stroke="#e8b84e" stroke-width="5"/><path d="M315 70h180M315 105h120M315 140h155" stroke="#7c9e83" stroke-width="13"/><path d="M145 190v35m-50 0h100" stroke="#35624d" stroke-width="12"/><circle cx="505" cy="205" r="30" fill="#e8b84e"/><path d="M490 205l10 10 20-25" fill="none" stroke="#123f35" stroke-width="5"/>`;
 if(type==='M'||type==='L')shapes=`<path d="M70 90h235l-22 95H98z" fill="#e8b84e"/><path d="M305 110h65l55 55v45H290v-45z" fill="#7c9e83"/><path d="M322 125h38l35 40h-73z" fill="#eaf0e5"/><rect x="65" y="185" width="365" height="30" rx="7" fill="#35624d"/><circle cx="140" cy="215" r="34" fill="#123f35"/><circle cx="350" cy="215" r="34" fill="#123f35"/><circle cx="140" cy="215" r="14" fill="#c4d9bd"/><circle cx="350" cy="215" r="14" fill="#c4d9bd"/><path d="M470 80v140M455 80h80l-20 25h-60" stroke="#35624d" fill="#e8b84e" stroke-width="7"/>`;
 if(type==='P')shapes=`<path d="M65 50h130l-20 90h-90z" fill="#7c9e83"/><path d="M130 140v30h140v-80h75" stroke="#35624d" stroke-width="12" fill="none"/><rect x="345" y="55" width="100" height="145" rx="15" fill="#c4d9bd"/><path d="M350 120h90v65q0 10-10 10h-70q-10 0-10-10z" fill="#76b3a0"/><path d="M395 200v35h120" stroke="#35624d" stroke-width="12" fill="none"/><circle cx="270" cy="170" r="22" fill="#e8b84e"/><path d="M250 170h40M270 150v40" stroke="#35624d" stroke-width="4"/>`;
 if(type==='E')shapes=`<path d="M30 210q70-45 140 0t140 0 140 0 120 0" fill="none" stroke="#77aaa0" stroke-width="25"/><path d="M170 185v-75m0 30q-75-5-60-65 65-5 60 65m0-10q65 0 65-55-65-5-65 55" fill="#7c9e83" stroke="#35624d" stroke-width="5"/><path d="M400 50q-70 85-35 115 35 35 70 0 35-30-35-115z" fill="#e8b84e"/><path d="M380 137q-8 25 18 25" fill="none" stroke="#fff4d4" stroke-width="6"/>`;
 return `<svg ${hero?'':'class="diagram"'} viewBox="0 0 600 280" role="img" aria-label="${hero?'Illustrated exploration landscape':esc(PATHS.find(p=>p.id===type)?.short+' learning illustration')}">${shapes}</svg>`;
}
function pathCard(p){const count=state.completed.filter(id=>id[0]===p.id).length;return `<article class="card"><div class="path-art"><span class="letter">${p.id}</span>${drawing(p.id)}</div><span class="pill">${p.role}</span><h3>${p.name}</h3><p>${p.desc}</p><div class="card-meta">5 modules · ${p.hours} guided programme hours · ${count}/5 complete</div><a class="path-link" href="#path/${p.id}">Explore pathway <span aria-hidden="true">→</span></a></article>`;}
function home(){nav('home');return `<section class="hero"><div><p class="eyebrow">LEARN IT. TRY IT. EXPLAIN IT.</p><h1>Build skills.<br>Make better<br>mining decisions.</h1><p>Clear lessons, topic videos, tutor support and a place to practise. Start with the foundations, then follow the pathway that fits your work.</p><div class="actions"><a class="button gold" href="#lesson/${state.last}">${state.notes[state.last]||state.quiz[state.last]?'Continue learning':'Start learning'} <span aria-hidden="true">→</span></a><a class="button light" href="#videos">Explore topic videos</a></div></div><div class="hero-art">${drawing('G',true)}</div></section><div class="stats"><div class="stat"><b>30</b><span>learner modules</span></div><div class="stat"><b>6</b><span>interactive practice labs</span></div><div class="stat"><b>90</b><span>questions with feedback</span></div><div class="stat"><b>${state.completed.length}</b><span>modules completed by you</span></div></div><div class="section-head"><div><p class="eyebrow">CHOOSE YOUR DIRECTION</p><h2>One foundation. Five specialisms.</h2><p>New to mining? Begin with the foundation before a specialist pathway.</p></div><a href="#guide">How the course works →</a></div><div class="grid">${PATHS.map(pathCard).join('')}</div><div class="notice"><strong>Your work stays with you.</strong> This course does not ask for your name or email. Notes and practice results stay in this browser. Export them regularly, especially on a shared computer. External providers have their own access and privacy terms.</div><div class="grid two"><article class="card"><p class="eyebrow">LEARNING BY DOING</p><h3>Practise a decision before it matters.</h3><p>Change the numbers. Inspect the evidence. Choose a response. Get feedback that explains why it works.</p><a href="#labs">Open the practice labs →</a></article><article class="card"><p class="eyebrow">BEYOND THIS COURSE</p><h3>Find the right simulation provider.</h3><p>Explore free science simulations and commercial mining systems, with access notes and a learning task for each.</p><a href="#resources">Browse verified provider links →</a></article></div>`;}
function courses(){nav('courses');return `<p class="eyebrow">YOUR COURSE MAP</p><h1>Choose a pathway.</h1><p class="intro">Complete the common foundation, then one specialism. You can explore every lesson here; professional practical tasks still need qualified supervision.</p><label for="search">Find a topic</label><input class="search" type="text" id="search" placeholder="Try sampling, AI, welding or water"><div id="search-results"></div><div class="grid" id="path-cards">${PATHS.map(pathCard).join('')}</div>`;}
function pathPage(id){const p=PATHS.find(p=>p.id===id);if(!p)return notFound();nav('courses');return `<p class="eyebrow">${p.id==='F'?'COMMON FOUNDATION':'SPECIALIST PATHWAY '+p.id}</p><h1>${p.name}</h1><p class="intro">${p.desc}</p><p class="small muted">${p.hours} guided programme hours · Five learning modules ${p.id!=='F'?'plus an integrated practical assessment week':''}</p><div class="notice">${p.id==='F'?'Start with the everyday concepts and practise them before choosing a specialist route.':'Recommended preparation: complete F1–F5, then work through these lessons in order.'} The web lessons support the programme hours; reading and quizzes alone do not replace the scheduled practical work.</div><div class="module-list">${BASE.modules.filter(m=>m.id[0]===id).map(m=>`<a class="module-row" href="#lesson/${m.id}"><span class="module-code">${m.id}</span><div><h3>${m.title}</h3><p>${LESSONS[m.id].hook}</p></div><span class="pill">${state.completed.includes(m.id)?'✓ Completed':state.notes[m.id]||state.quiz[m.id]||state.videoNotes?.[m.id]?'In progress':'Start →'}</span></a>`).join('')}</div><div class="grid two" style="margin-top:25px"><article class="card"><h3>${p.lab}</h3><p>Practise the key decisions and record your reasoning.</p><a href="#lab/${id}">Enter the lab →</a></article><article class="card"><h3>Pathway final project</h3><p>Bring your evidence together and prepare for an individual assessor review.</p><a href="#project/${id}">View project brief →</a></article></div>`;}
function lesson(id){const m=BASE.modules.find(m=>m.id===id),l=LESSONS[id];if(!m||!l)return notFound();if(l._stub)return lockedPage('lesson',id);nav('courses');state.last=id;save();const ix=BASE.modules.findIndex(x=>x.id===id),next=BASE.modules[ix+1];return `<a href="#path/${id[0]}" class="small">← ${PATHS.find(p=>p.id===id[0]).short} pathway</a><h1 class="lesson-title">${id} · ${m.title}</h1><p class="intro small">${inline(m.overview)}</p><div class="hook">${l.hook}</div><div class="lesson-layout"><div class="lesson-body"><section class="card" id="understand"><p class="eyebrow">01 / UNDERSTAND</p><h2>The idea, in plain English</h2>${drawing(id[0])}<div class="step-series">${l.simple.map(([h,t])=>`<div class="step-card"><div><h3>${h}</h3><p>${t}</p></div></div>`).join('')}</div><div class="terms">${Object.entries(l.terms).map(([k,v])=>`<div class="term"><b>${k.replace(/([a-z])([A-Z])/g,'$1 $2')}</b><p>${v}</p></div>`).join('')}</div><details><summary>Go deeper: technical explanation</summary><div>${md(m.Learn)}</div></details></section>${videoSection(id)}<section class="card" id="example"><p class="eyebrow">02 / SEE IT WORK</p><h2>A worked example</h2><div class="worked">${md(m['Worked example'])}</div><p class="small muted" style="margin-top:15px">Read once, cover the example, and explain the reasoning in your own words. Check units and assumptions before comparing answers.</p></section>${tutorSection(id)}<section class="card workbook" id="practice"><p class="eyebrow">03 / TRY IT YOURSELF</p><h2>Your practical activity</h2><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><details><summary>Extend it: paired or facilitated activity</summary><div>${md(m['Practice and activity'])}</div></details><label for="notes">Your working, explanation and next action</label><p class="small muted">Include your method, units, evidence, uncertainty and what you would do next. Use fictional information only. At least 80 characters are needed to record module completion.</p><textarea id="notes" data-module="${id}" placeholder="My method…\nMy result and evidence…\nWhat remains uncertain…\nMy next action and who should decide…">${esc(state.notes[id]||'')}</textarea><p class="small muted" id="note-count">${(state.notes[id]||'').length} characters · autosaved as you type</p><details><summary>Compare your work with the feedback guide</summary><div>${md(m['Check and feedback'])}<p>Use this to improve your explanation. It is a practice guide, not an independent assessment result.</p></div></details></section><section class="card" id="apply"><p class="eyebrow">04 / APPLY THE IDEA</p><h2>Make a decision</h2>${md(m['Simulation and evidence'])}<a class="button" href="#lab/${id[0]}">Open ${PATHS.find(p=>p.id===id[0]).lab} →</a><p class="source" style="margin-top:14px">Use the lab to rehearse the reasoning. S0–S5 and A0–A5 references refer to the facilitated case packs and project briefs in this course.</p></section><section class="card" id="check"><p class="eyebrow">05 / CHECK YOUR UNDERSTANDING</p><h2>Can you explain the choice?</h2><p class="small muted">Three practice questions. Submit all three for feedback; you can retry after reviewing the lesson.</p><form id="quiz" data-id="${id}">${l.quiz.map(([q,a],i)=>`<fieldset class="question"><legend>${i+1}. ${q}</legend>${a.map((v,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" ${state.quiz[id]?.answers[i]===j?'checked':''} required><span>${v}</span></label>`).join('')}<div id="qfb${i}" class="feedback" aria-live="polite"></div></fieldset>`).join('')}<button type="submit">Check my answers</button></form><div id="quiz-result" class="feedback" role="status">${state.quiz[id]?`Last practice result: ${state.quiz[id].score}/3. Submit again to review explanations.`:''}</div></section><div class="complete-bar"><h3>Ready to move on?</h3><p>Module completion means all three practice questions are correct and you have recorded your own activity response. It is a learning milestone, not assessed workplace competence.</p><button id="complete" data-id="${id}">${state.completed.includes(id)?'✓ Module completed':'Mark module complete'}</button>${next?` <a class="button light" href="#lesson/${next.id}">Next: ${next.id} →</a>`:` <a class="button light" href="#project/E">Open final project →</a>`}</div></div><aside class="lesson-sidebar"><div class="card"><h3>IN THIS LESSON</h3><a href="#understand" data-scroll="understand">01 · Understand</a><a href="#watch" data-scroll="watch">▷ · Topic video</a><a href="#tutor" data-scroll="tutor">✦ · Tutor & study tools</a><a href="#example" data-scroll="example">02 · Worked example</a><a href="#practice" data-scroll="practice">03 · Your activity</a><a href="#apply" data-scroll="apply">04 · Simulation</a><a href="#check" data-scroll="check">05 · Knowledge check</a><p class="small muted" style="margin-top:20px">Take a break after each section. Return to your saved notes whenever you need.</p><div class="actions"><a href="#resources">External simulations ↗</a></div></div></aside></div>`;}
function labs(){nav('labs');return `<p class="eyebrow">A SAFE PLACE TO PRACTISE</p><h1>Change a variable.<br>See what follows.</h1><p class="intro">These six browser labs model decisions and simple calculations. Every dataset, trigger and scenario is fictional. Each lab includes a task, feedback and a place to record your reasoning.</p><div class="grid">${PATHS.map(p=>`<article class="card"><div class="path-art"><span class="letter">${p.id}</span>${drawing(p.id)}</div><span class="pill">Runs here · no extra account</span><h3>${p.lab}</h3><p>${labDescriptions[p.id]}</p><a class="path-link" href="#lab/${p.id}">Start practice <span>→</span></a></article>`).join('')}</div><div class="notice">These are teaching models and decision scenarios, not engineering digital twins or machine-control simulators. For industrial systems and VR, visit <a href="#resources">simulation providers</a>.</div>`;}
const labDescriptions={F:'Explore precision, recall and why accuracy can hide missed faults.',G:'Inspect targets on a local grid. Balance promising results against custody, quality and access.',M:'Work through a changing shift. Make safe decisions under production pressure.',P:'Calculate yield and recovery, check a balance and track a tank during outflow failure.',L:'Build a delivery plan that respects vehicle holds, route closures and available time.',E:'Investigate a rain event without turning missing readings into false reassurance.'};
function field(id,label,value,min=0,max=10000,step='any'){return `<label for="${id}">${label}<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;}
function labPage(id){const p=PATHS.find(p=>p.id===id);if(!p)return notFound();nav('labs');const s=BASE.sections.find(x=>x.title.startsWith('S'+PATHS.indexOf(p)+' '));if(!s)return lockedPage('lab',id);return `<a href="#labs" class="small">← All practice labs</a><p class="eyebrow" style="margin-top:22px">${p.short} / INTERACTIVE PRACTICE</p><h1 class="lesson-title">${p.lab}</h1><p class="intro">${labDescriptions[id]}</p><div class="notice"><strong>Exercise scope:</strong> use only the fictional rules and data shown. These are learning exercises, not instructions or settings for real equipment.</div><div id="lab-content">${({F:labAI,G:labGeo,M:labOps,P:labProcess,L:labDispatch,E:labEnvironment}[id])()}</div><section class="card workbook" style="margin-top:25px"><h2>Capture your learning</h2><p>Record your starting conditions, calculation or choice, result, uncertainty and what you would do differently. Use at least two different runs.</p><label for="lab-notes">My lab evidence</label><textarea id="lab-notes" data-path="${id}" placeholder="Run 1: conditions, prediction, result…\nRun 2: what I changed and what happened…\nMy decision, limitations and next action…">${esc(state.labs[id]||'')}</textarea><button class="light" id="capture-lab" data-path="${id}" style="margin-top:12px">Add current lab result to my notes</button><div class="actions"><a href="#project/${id}">Continue to the pathway project →</a></div></section><details><summary>Facilitated group case: ${esc(s?.title||'')}</summary><div>${md(s?.body||'')}<p class="small muted">The case includes facilitator guidance and model responses. Use it for practice; a trainer should change the case for an independent assessment.</p></div></details>`;}
function labAI(){return `<div class="lab-grid"><section class="card"><h2>How reliable are these alarms?</h2><p>There are always 100 cases, including 10 real faults. Change the detected faults and false alarms. Predict which metric will change before recalculating.</p><form id="ai-form"><div class="controls">${field('tp','Real faults detected',8,0,10,1)}${field('fp','False alarms',12,0,90,1)}</div><button style="margin-top:20px">Calculate model performance</button></form><div class="actions"><button class="light" id="always-normal">Try “always normal”</button><button class="light" id="ai-reset">Restore example</button></div></section><section class="card"><h2>Evidence, not just a headline</h2><div id="ai-output" class="lab-output" aria-live="polite"></div></section></div><div class="card" style="margin-top:22px"><h3>Your investigation</h3><ol><li>Calculate the starting precision and recall by hand.</li><li>Keep eight detected faults but reduce false alarms to four. Explain what improves and what does not.</li><li>Try “always normal”. Explain why its accuracy cannot justify its use as a fault detector.</li></ol><p><strong>Decision:</strong> retain qualified review and independent validation. No metric here grants operational approval.</p></div>`;}
const targets=[{id:'A',x:100,y:200,assay:120,score:.4,status:'Intact seal; access permitted'},{id:'B',x:250,y:300,assay:250,score:.7,status:'Intact seal; access permitted'},{id:'C',x:400,y:600,assay:900,score:.95,status:'Broken seal; custody review required'},{id:'D',x:600,y:200,assay:180,score:.45,status:'Intact seal; access permitted'},{id:'E',x:500,y:450,assay:620,score:.85,status:'Intact seal; access permitted'},{id:'F',x:700,y:650,assay:700,score:.9,status:'Access permission not available'}];
function labGeo(){return `<div class="lab-grid"><section class="card"><h2>A target is a question</h2><svg class="gridmap" viewBox="0 0 500 450" role="img" aria-label="Six fictional targets on a local grid in metres. Full coordinates are in the table below."><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#c5d5bd"/></pattern></defs><rect x="40" y="30" width="410" height="350" fill="url(#grid)"/><path d="M40 30V380H450" stroke="#35624d" stroke-width="2" fill="none"/><text x="210" y="425" font-size="14" fill="#123f35">Local easting (m)</text><text x="45" y="22" font-size="12" fill="#123f35">North ↑ · local northing (m)</text>${targets.map(t=>`<circle cx="${40+t.x/2}" cy="${380-t.y/2}" r="13" fill="${t.id==='C'||t.id==='F'?'#e8b84e':'#35624d'}"/><text x="${40+t.x/2}" y="${385-t.y/2}" text-anchor="middle" font-size="13" fill="${t.id==='C'||t.id==='F'?'#123f35':'white'}">${t.id}</text>`).join('')}<text x="40" y="400" font-size="11">0</text><text x="235" y="400" font-size="11">400</text><text x="435" y="400" font-size="11">800</text></svg><p class="source">Local classroom grid in metres; not real geographic coordinates. Assays below are fictional ppm of an unspecified target element and have unresolved batch QC.</p></section><section class="card"><h2>Choose the next investigation</h2><p>A batch blank reads 25 ppm against an exercise review trigger of 10 ppm. All model scores are uncalibrated rankings, not probabilities.</p><div class="controls"><label for="geo-target">Provisional target<select id="geo-target">${targets.map(t=>`<option>${t.id}</option>`).join('')}</select></label><label for="geo-action">Next action<select id="geo-action"><option value="review">Desk review: resolve quality and access</option><option value="drill">Proceed directly to drilling</option><option value="reserve">Declare an economic reserve</option></select></label></div><button id="geo-check" style="margin-top:20px">Review my decision</button><div id="geo-output" class="feedback" role="status"></div><p><strong>Challenge:</strong> explain why E may be a provisional priority, but is not yet cleared for fieldwork or reliable grade interpretation.</p></section></div><div class="card" style="margin-top:22px"><div class="table-wrap"><table><thead><tr><th>Target</th><th>Easting / northing (m)</th><th>Reported assay (ppm)</th><th>Model score</th><th>Evidence status</th></tr></thead><tbody>${targets.map(t=>`<tr><td>${t.id}</td><td>${t.x} / ${t.y}</td><td>${t.assay}</td><td>${t.score}</td><td>${t.status}</td></tr>`).join('')}</tbody></table></div><p><strong>Change card:</strong> heavy rain affects the planned route. Add current route review to the hold points. Do not substitute invented observations for cancelled fieldwork.</p></div>`;}
let ops={variant:0,step:0,log:[],failed:false,done:false};
const opsRuns=[[
['Pre-use check','A critical protection defect is recorded. The dispatcher wants the truck immediately.',['Hold the task and notify the authorised supervisor','Start carefully and repair it later','Clear the defect yourself'],0,'The unresolved critical defect prevents this simulated task. Record it and seek authorised review.'],
['Clearance card','The authorised supervisor supplies explicit clearance after the defect has been resolved. The route and communications checks are current.',['Begin the planned simulator task under the stated controls','Ignore the clearance and invent a new defect','Change the machine settings without permission'],0,'This card clears the stated defect. Continue only under the existing route, exclusion and communication controls.'],
['Route change','A pedestrian enters the exclusion area. You are behind the shift target.',['Use the horn and continue','Hold the affected task under the exercise rule and report','Accelerate past the pedestrian'],1,'The exclusion control is compromised. Meeting the target does not justify continuing.'],
['Reassuring AI','The display is frozen at 10:00. An AI message says failure is unlikely. There is no new clearance.',['Treat the AI score as clearance','Restart because the display is green','Maintain the hold, report stale data and request approved information'],2,'A probability does not restore current evidence or authorise restart.']
],[
['Second run: communications','Required communication is lost before the route starts. The weather is clear.',['Hold the affected task and report through the approved fallback','Start because the road looks empty','Use yesterday’s radio check'],0,'Current required communication is a condition for this exercise.'],
['Second run: pressure','A colleague says the radio fault is minor. No authorised clearance has arrived.',['Accept the colleague’s opinion','Keep the hold and request the authorised decision','Mark the fault repaired'],1,'Informal reassurance cannot replace the stated clearance condition.'],
['Second run: release','An authorised card confirms communications restored, route clear and the required checks complete.',['Resume the defined simulator task under the controls','Bypass future checks to regain time','Change the load limit'],0,'The specific release permits the defined task, not changes to other controls.'],
['Second run: handover','The next operator asks whether an AI maintenance prediction proves the machine will not fail.',['Say yes because the model is accurate','Delete the alert','Explain its uncertainty and preserve the observation for qualified review'],2,'Predictions support investigation; they do not guarantee equipment condition.']
]];
function labOps(){return `<div class="lab-grid"><section class="card"><h2>Safe decisions under pressure</h2><p>Four decisions per run. An unsafe choice ends the run. Review the feedback, restart, and then try the changed second run.</p><div class="notice">Rule card: critical defect, pedestrian incursion, lost required communication or stale safety information → hold the affected simulated task and notify the supervisor. Restart needs explicit authorised clearance.</div><div class="actions"><button id="ops-restart" class="light">Restart this run</button><button id="ops-variant" class="light">Try the other run</button></div><div id="ops-log" class="scenario-log"></div></section><section class="card"><div id="ops-stage" aria-live="polite"></div></section></div><section class="card" style="margin-top:22px"><h3>Shift report calculation</h3><p>Scheduled time: 8 h. Equipment unavailable: 2 h. Productive: 4.5 h. Calculate availability, utilisation of available time and productive share of scheduled time.</p><details><summary>Check the calculations</summary><div><p>Available = 6 h. Availability = 6/8 = 75%. Utilisation of available time = 4.5/6 = 75%. Productive share of scheduled time = 4.5/8 = 56.25%. Always name the denominator.</p></div></details></section>`;}
function renderOps(){const s=opsRuns[ops.variant][ops.step];document.getElementById('ops-log').innerHTML=ops.log.map(t=>`<p>${esc(t)}</p>`).join('');const el=document.getElementById('ops-stage');if(ops.failed){el.innerHTML=`<span class="pill red">Run ended · review needed</span><h3 style="margin-top:18px">The choice broke a critical rule.</h3><p>${esc(ops.log.at(-1))}</p><p>Use “Restart this run”, explain the rule in your notes, and try again.</p>`;return;}if(ops.done){el.innerHTML='<span class="pill">4 / 4 decisions completed</span><h3 style="margin-top:18px">The restrictions stayed visible.</h3><p>You responded correctly in this scenario. Capture your decision log, then try the other run. This is classroom practice, not real-machine assessment.</p>';return;}el.innerHTML=`<p class="eyebrow">RUN ${ops.variant+1} · DECISION ${ops.step+1} OF 4</p><h2>${s[0]}</h2><p>${s[1]}</p>${s[2].map((a,i)=>`<button class="scenario-option" data-choice="${i}">${a}</button>`).join('')}`;el.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const choice=Number(b.dataset.choice);ops.log.push(`Decision ${ops.step+1}: ${s[2][choice]}. ${s[4]}`);if(choice!==s[3])ops.failed=true;else if(++ops.step===4)ops.done=true;renderOps();});}
function labProcess(){return `<div class="lab-grid"><section class="card"><h2>1. Balance the material</h2><p>Dry mass only. Use the same Li₂O basis throughout. The model has feed, concentrate and tailings, with no accumulation or other streams.</p><form id="mass-form"><div class="controls">${field('feed','Feed mass (t)',100,.01,10000)}${field('feedgrade','Feed grade (%)',1.2,.001,100)}${field('conc','Concentrate mass (t)',15,0,10000)}${field('concgrade','Concentrate grade (%)',6,0,100)}</div><button style="margin-top:20px">Check the balance</button></form><div id="mass-output" aria-live="polite"></div></section><section class="card"><h2>2. Watch the tank</h2><p>Starts at 40 m³. Inflow 12 m³/h. Outflow 10 m³/h in hour one, then fails to zero. Exercise trigger: 50 m³.</p><label for="tank-time">Elapsed minutes <output id="tank-minutes">0</output></label><input type="range" id="tank-time" min="0" max="120" value="0" step="5" style="width:100%"><div class="tank-wrap"><div class="tank" aria-hidden="true"><div class="tank-water" id="water"></div><div class="tank-mark">50 m³ trigger</div></div><div id="tank-output" aria-live="polite"></div></div><button class="light" id="tank-response" style="margin-top:20px">Choose the protective response</button><div id="tank-feedback" class="feedback"></div></section></div><section class="card" style="margin-top:22px"><h2>3. Check the quality hold</h2><p>Blank = 25 ppm (review above 10). Reference = 112 ppm (accept 95–105). Duplicates = 100 and 110 ppm (review RPD above 15%). These criteria apply only to this fictional exercise.</p><button class="light" id="qc-hold">Hold for authorised QC review</button> <button class="light" id="qc-release">Release because duplicates agree</button><div class="feedback" id="qc-output" role="status"></div><p><strong>Challenge:</strong> change concentrate mass to 12 tonnes at the same grade. Compare yield, recovery and product grade. Then find when the unmitigated tank reaches its trigger.</p></section>`;}
function labDispatch(){return `<div class="lab-grid"><section class="card"><h2>Build a feasible plan</h2><p>A and B are available. Each carries 20 tonnes per trip. C is on maintenance hold. Route 1 is closed. Route 2 is open. The cycle includes loading, travel, unloading and return.</p><form id="dispatch-form"><div class="controls">${field('window','Operating window (hours)',6,1,12,.5)}${field('cycle','Cycle duration (minutes)',90,30,240,15)}${field('demand','Demand (tonnes)',120,1,1000,1)}<label for="truck-c">Truck C<select id="truck-c"><option value="hold">Keep on maintenance hold</option><option value="use">Use without clearance</option></select></label><label for="route">Route<select id="route"><option value="2">Route 2 · open</option><option value="1">Route 1 · closed</option></select></label></div><button style="margin-top:20px">Evaluate dispatch plan</button></form></section><section class="card"><h2>Capacity and constraints</h2><div id="dispatch-output" aria-live="polite"></div></section></div><section class="card" style="margin-top:22px"><h3>Now handle the records</h3><p>Stock: opening 100, receipts 40, issues 55, count 82. Batch seal says BX12, assay document says BX21.</p><p>Calculate the stock difference and describe the document hold. Do not correct one identifier without supporting evidence.</p><details><summary>Compare your reconciliation</summary><div><p>Expected stock: 85. Physical shortage: 3. Investigate the stock difference and hold the mismatched shipment records for authorised reconciliation. Neither can be fixed by an AI guess.</p></div></details><p><strong>Challenge:</strong> increase cycle time to 120 minutes, then reduce the window to five hours. Explain the delivery shortfall and an honest customer update.</p></section>`;}
function labEnvironment(){return `<div class="lab-grid"><section class="card"><h2>Read the event</h2><div class="table-wrap"><table><thead><tr><th>Day</th><th>Rain mm</th><th>Upstream NTU</th><th>Downstream NTU</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>5</td><td>8</td></tr><tr><td>2</td><td>5</td><td>6</td><td>10</td></tr><tr><td>3</td><td>40</td><td>8</td><td>45</td></tr><tr><td>4</td><td>60</td><td>9</td><td>Unknown · offline</td></tr></tbody></table></div><p>Exercise trigger: downstream minus upstream above 20 NTU requires investigation. Lost monitoring during heavy rain requires escalation. Neither is a legal limit.</p><form id="env-form"><div class="controls">${field('upstream','Upstream NTU',8,0,1000)}${field('downstream','Downstream NTU',45,0,1000)}</div><button style="margin-top:20px">Compare readings</button></form><div id="env-output" class="feedback" role="status"></div></section><section class="card"><h2>The dashboard is green</h2><p>It is day 4. The green icon uses day 2 data. A farmer reports discoloured water. Choose your briefing.</p><button class="scenario-option" data-env="0">“No problem: the dashboard is green.”</button><button class="scenario-option" data-env="1">“The mine definitely caused the change.”</button><button class="scenario-option" data-env="2">“Current status is unknown. Preserve the complaint, escalate missing monitoring and investigate the earlier rise.”</button><div id="env-decision" class="feedback" role="status"></div><p><strong>Communication task:</strong> acknowledge the concern, name the investigation owner and give a next update time without promising the outcome.</p></section></div><section class="card" style="margin-top:22px"><h3>Extend the investigation</h3><p>Calculate seedling survival for 150 of 200, and emissions for 1,000 litres using the teaching-only factor 2.70 kg CO₂e/litre. Explain why neither proves “fully sustainable”.</p><details><summary>Check and explain</summary><div><p>Survival: 75%. Fuel estimate: 2.7 tonnes CO₂e. Survival is only one rehabilitation measure; this fuel estimate has a limited assumed boundary and factor. Further evidence is needed for broader claims.</p></div></details></section>`;}
let currentLabResult='';
function calcAI(){const tp=Number(document.getElementById('tp').value),fp=Number(document.getElementById('fp').value);if(!Number.isInteger(tp)||!Number.isInteger(fp)||tp<0||tp>10||fp<0||fp>90)return;const fn=10-tp,tn=90-fp,precision=tp+fp?100*tp/(tp+fp):null,recall=tp*10,accuracy=tp+tn;currentLabResult=`AI lab: TP ${tp}, FP ${fp}, FN ${fn}, TN ${tn}. Precision ${precision===null?'undefined (no alarms)':precision.toFixed(1)+'%'}, recall ${recall}%, accuracy ${accuracy}%.`;document.getElementById('ai-output').innerHTML=`<table><thead><tr><th></th><th>Actual fault</th><th>No fault</th></tr></thead><tbody><tr><th>Alarm</th><td>${tp} detected</td><td>${fp} false alarms</td></tr><tr><th>No alarm</th><td>${fn} missed</td><td>${tn} correct normal</td></tr></tbody></table><div class="metrics"><div class="metric"><b>${precision===null?'—':precision.toFixed(1)+'%'}</b><small>Precision${precision===null?' · no alarms':''}</small></div><div class="metric"><b>${recall}%</b><small>Recall</small></div><div class="metric"><b>${accuracy}%</b><small>Accuracy</small></div></div><p class="small">${fn} of 10 real faults were missed. ${fp} of ${tp+fp} alarms were false. ${tp===0?'A detector that finds no faults has no demonstrated fault-detection value here, even if accuracy looks high.':'Compare the consequences of missed events and false alarms; do not use a single percentage as a safety release.'}</p>`;}
function calcMass(){const f=Number(document.getElementById('feed').value),fg=Number(document.getElementById('feedgrade').value),c=Number(document.getElementById('conc').value),cg=Number(document.getElementById('concgrade').value),el=document.getElementById('mass-output');const fc=f*fg/100,cc=c*cg/100,t=f-c,tc=fc-cc;if(f<=0||fg<=0||fg>100||c<0||cg<0||cg>100||c>=f||cc>fc+1e-9||tc>t+1e-9){currentLabResult='Processing lab: invalid balance rejected. Concentrate cannot exceed available mass or component, and tailings must remain physically possible.';el.innerHTML='<div class="feedback bad">These inputs cannot form a valid two-product balance in this model. Check that concentrate mass is below feed mass, component in concentrate does not exceed component in feed, and tailings grade is between 0 and 100%.</div>';return;}const y=c/f*100,r=cc/fc*100,tg=tc/t*100;currentLabResult=`Processing lab: feed ${f} t at ${fg}% Li₂O; concentrate ${c} t at ${cg}%. Yield ${y.toFixed(2)}%, recovery ${r.toFixed(2)}%, tailings ${t.toFixed(2)} t at ${tg.toFixed(3)}%.`;el.innerHTML=`<div class="metrics two"><div class="metric"><b>${y.toFixed(1)}%</b><small>Mass yield</small></div><div class="metric"><b>${r.toFixed(1)}%</b><small>Component recovery</small></div></div><p class="small">Feed component: <b>${fc.toFixed(3)} t</b><br>Concentrate component: <b>${cc.toFixed(3)} t</b><br>Tailings: <b>${t.toFixed(2)} t at ${tg.toFixed(3)}% Li₂O</b></p><p class="source">Yield = concentrate/feed. Recovery = concentrate component/feed component. This checks arithmetic, not assay validity.</p>`;}
function calcTank(){const min=Number(document.getElementById('tank-time').value),level=min<=60?40+2*min/60:42+12*(min-60)/60;document.getElementById('tank-minutes').textContent=min+' min';document.getElementById('water').style.height=level/60*100+'%';document.getElementById('tank-output').innerHTML=`<div class="metric"><b>${level.toFixed(1)} m³</b><small>Unmitigated model level</small></div><p class="small" style="margin-top:12px">${min<60?'Outflow operating.':min<100?'Outflow failed. Level rising.':'At or above the exercise trigger.'}</p>`;document.getElementById('tank-output').dataset.result=`Tank at ${min} min: ${level.toFixed(1)} m³ (unmitigated). Trigger at 100 min from start, 40 min after failure.`;}
function calcDispatch(){const h=Number(document.getElementById('window').value),cy=Number(document.getElementById('cycle').value),d=Number(document.getElementById('demand').value),bad=document.getElementById('truck-c').value==='use'||document.getElementById('route').value==='1',el=document.getElementById('dispatch-output');if(h<=0||cy<=0||d<=0)return;if(bad){currentLabResult='Dispatch plan rejected: it relies on an uncleared truck or a closed route.';el.innerHTML='<div class="feedback bad"><strong>Plan rejected.</strong> A held truck or closed route cannot be used in this exercise. Restore the constraints before calculating an executable plan.</div>';return;}const cycles=Math.floor(h*60/cy),capacity=cycles*2*20,deliver=Math.min(capacity,d),short=Math.max(0,d-capacity),trips=Math.ceil(deliver/20);currentLabResult=`Dispatch: ${h} h window, ${cy} min cycles, 2 trucks × 20 t. ${cycles} cycles per truck; ${capacity} t theoretical capacity; ${deliver} t deliverable; ${short} t shortfall. Route 2 only; C held.`;el.innerHTML=`<div class="metrics two"><div class="metric"><b>${capacity} t</b><small>Theoretical capacity</small></div><div class="metric"><b>${short} t</b><small>Shortfall vs demand</small></div></div><p>${cycles} complete cycles per truck. ${trips} loaded trips needed for the feasible ${deliver} t ${deliver%20?'(last load partly filled)':''}.</p><p class="small">Capacity = floor(${h} × 60 / ${cy}) × 2 × 20.</p><div class="feedback ${short?'bad':''}">${short?'Renegotiate quantity or timing through an authorised plan. Do not overload or bypass a hold.':capacity===d?'Demand exactly equals theoretical capacity. There is no spare capacity for extra delay.':'The simplified model has spare capacity. Check all real constraints before making a commitment.'}</div>`;}
function calcEnv(){const u=Number(document.getElementById('upstream').value),d=Number(document.getElementById('downstream').value),diff=d-u;currentLabResult=`Environment lab: upstream ${u} NTU, downstream ${d} NTU, difference ${diff} NTU. ${diff>20?'Exercise investigation trigger exceeded.':'Exercise difference trigger not exceeded; this alone does not prove compliance or safety.'}`;const el=document.getElementById('env-output');el.textContent=currentLabResult;el.className='feedback'+(diff>20?' bad':'');}
function setupLab(id){currentLabResult='';const on=(id,fn)=>{document.getElementById(id).onclick=fn;};if(id==='F'){calcAI();document.getElementById('ai-form').onsubmit=e=>{e.preventDefault();calcAI();};on('always-normal',()=>{document.getElementById('tp').value=0;document.getElementById('fp').value=0;calcAI();});on('ai-reset',()=>{document.getElementById('tp').value=8;document.getElementById('fp').value=12;calcAI();});}if(id==='G'){on('geo-check',()=>{const t=targets.find(t=>t.id===document.getElementById('geo-target').value),a=document.getElementById('geo-action').value,good=a==='review';currentLabResult=`Target ${t.id}: ${t.status}. ${good?'Desk review is appropriate. Resolve the blank failure and the scope of any affected results before relying on assays. '+(t.id==='C'?'Broken custody needs separate review.':t.id==='F'?'Access must be resolved before any field task.':'Access permission alone does not resolve batch quality.'):'Decision not supported. No target is cleared by these data for direct drilling or a reserve claim.'}`;const el=document.getElementById('geo-output');el.textContent=currentLabResult;el.className='feedback'+(!good?' bad':'');});}if(id==='M'){ops={variant:0,step:0,log:[],failed:false,done:false};renderOps();on('ops-restart',()=>{ops={variant:ops.variant,step:0,log:[],failed:false,done:false};renderOps();});on('ops-variant',()=>{ops={variant:1-ops.variant,step:0,log:[],failed:false,done:false};renderOps();});}if(id==='P'){calcMass();calcTank();document.getElementById('mass-form').onsubmit=e=>{e.preventDefault();calcMass();};document.getElementById('tank-time').oninput=calcTank;on('tank-response',()=>{document.getElementById('tank-feedback').textContent='Exercise safe-state card: halt the affected simulated feed and notify the authorised control lead. Never bypass protection. The tank display above remains an unmitigated prediction so you can study the timing; it does not simulate the protective action.';});on('qc-hold',()=>{document.getElementById('qc-output').textContent='Correct: hold for authorised review. Both blank and reference fail the fictional criteria. Duplicate RPD is 9.52%, but that does not cancel the failures.';});on('qc-release',()=>{document.getElementById('qc-output').textContent='Do not release: the blank and reference failures remain unresolved. Passing duplicates only answer one quality question.';});}if(id==='L'){calcDispatch();document.getElementById('dispatch-form').onsubmit=e=>{e.preventDefault();calcDispatch();};}if(id==='E'){calcEnv();document.getElementById('env-form').onsubmit=e=>{e.preventDefault();calcEnv();};document.querySelectorAll('[data-env]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.env),txt=['A stale green icon is not current evidence. Day 4 is unknown and needs escalation.','The data show a change, not its cause. Investigate without asserting unsupported causation.','Appropriate: keep unknown status visible, preserve the concern and follow the exercise escalation rule.'][n];document.getElementById('env-decision').textContent=txt;document.getElementById('env-decision').className='feedback'+(n===2?'':' bad');currentLabResult+=' Briefing choice: '+b.textContent+' Feedback: '+txt;});}}
const providers=[
{name:'PhET · Density',tag:'Free browser simulation',path:'P2 · science foundations',url:'https://phet.colorado.edu/en/simulations/density',desc:'University of Colorado Boulder simulation for exploring mass, volume and density. Useful preparation for separation concepts; it is not a mineral-processing plant model.',access:'Open the simulation page and select play. Browser access; no mine simulator hardware required. Provider terms apply.',task:'Compare equal-volume blocks with different masses. Predict whether each floats, test it, then explain why particle size and shape would also matter in a real separation process.',deliver:'A four-row prediction/result table and a 100-word explanation.'},
{name:'Metso Academy · Operator Training Simulator',tag:'Online commercial simulation',path:'P1–P5 · processing',url:'https://www.metso.com/products-and-services/services/training-academy/',desc:'Metso describes generic online operator simulators for mineral-processing and hydrometallurgical areas, plus plant-specific systems.',access:'Institutional or commercial arrangement: contact Metso about licences, course delivery and the circuit you need. No free learner seat or access entitlement is included here.',task:'After access is arranged, use the provider’s approved scenario to compare a stable baseline with a process disturbance. Record variables, response and recovery. Use the built-in processing lab while waiting for access.',deliver:'A trend record, decision log and provider/instructor debrief.'},
{name:'ANDRITZ · IDEAS / Metris OTS',tag:'Commercial · deployment to confirm',path:'P5 · process control',url:'https://www.andritz.com/products-en/spectrum/automation/simulation/ideas-simulation-solution',desc:'Industrial process-modelling software with mineral-processing libraries. The provider lists software-as-a-service and student/university licensing options; OTS solutions support operator training.',access:'Request a quote and written confirmation of browser/cloud access, installation, concurrent seats and training scenarios. A listed SaaS option does not prove that an anonymous browser demo is available.',task:'Request an instructor-led inventory or pump-failure exercise. Compare a prediction from a simple balance with the configured model and explain differences.',deliver:'Assumptions, predicted trend, observed trend and a model-limits note.'},
{name:'Immersive Technologies · WorksiteVR Quest',tag:'Commercial VR · hardware required',path:'M1–M4 · hazard awareness',url:'https://www.immersivetechnologies.com/products/WorksiteVR.htm',desc:'Virtual worksite scenarios for surface and underground awareness, hazards and emergency situations.',access:'Contact the provider for hardware, licence, local support and instructor requirements. The product name does not establish Meta headset compatibility or cloud delivery.',task:'With a qualified instructor, identify hazards, apply the scenario controls and explain the response to an unexpected event. Use the safe-shift browser lab as the accessible alternative.',deliver:'Two observed scenario records with feedback and an explanation of transfer limits.'},
{name:'Immersive Technologies · Virtual Machine',tag:'Commercial blended learning',path:'M2–M3 · inspection and controls',url:'https://www.immersivetechnologies.com/products/Virtual-Machine.htm',desc:'A set of learning products covering equipment knowledge, pre-start inspection, controls and tasks.',access:'Enquire about the actual machine configuration and delivery platform. Hardware, hosted access and licensing must be confirmed; this is not labelled a free cloud simulator.',task:'Compare two pre-start fault scenarios on the contracted equipment model. Identify what requires a hold and who may clear it.',deliver:'A pre-use record, defect report and a trainer-observed explanation.'},
{name:'QGIS · Training Manual',tag:'Free desktop GIS · not a simulator',path:'G1–G3 · geospatial practice',url:'https://docs.qgis.org/3.44/en/docs/training_manual/',desc:'Official guided GIS exercises for map layers, styling, layouts and spatial work. Use with a QGIS installation.',access:'Manual is online; QGIS runs on a computer. Use only fictional or approved datasets. This link is a practical tool pathway, not a cloud mining simulation.',task:'Create a delimited-text layer from the supplied target CSV using an explicitly documented local engineering grid. Alternatively plot on squared paper. Add a legend, units and source note; do not assign a geographic CRS to fictional coordinates.',deliver:'A map PDF or screenshot and the source table, with coordinate limitations stated.'},
{name:'Gillette College · Mining safety VR',tag:'Free VR programs · headset required',path:'M1–M3 · L4 · hazard awareness',url:'https://gillettecollege.org/academics/safety-training-programs/',desc:'Free Unity VR programs built with mining partners: Blind Spot (360° photos of large-equipment blind spots), Light Duty Vehicle Inspection and Working at Heights.',access:'Programs are free with a US$10 shipping and handling fee; built for Meta Quest 2 (newer Quest headsets are the practical choice). Submit the college’s order form and ask about delivery to Nigeria.',task:'In Blind Spot, map every position from which a pedestrian is invisible to the operator. Compare with the haul-road rules in the safe-shift lab.',deliver:'A blind-spot sketch and three controls ranked by effectiveness.'},
{name:'NIOSH · EXAMiner',tag:'Free desktop tool · US government',path:'F1 · M1 · workplace examination',url:'https://www.cdc.gov/niosh/publications/numbered/2020-121.html',desc:'Windows software in which mineworkers search panoramic mine scenes for hazards within a time limit and receive feedback. Trainers can load their own photographs.',access:'Published by NIOSH for mining training on Windows PCs. Check the NIOSH Mining website for the current download before planning a session.',task:'Complete one timed scene, then list the hazards you missed and why they were easy to overlook.',deliver:'Score screenshot, missed-hazard list and one change to your inspection routine.'},
{name:'Interplay Learning · Skilled trades',tag:'Subscription · browser + VR',path:'M3 · L3 · L4 · maintenance and trades',url:'https://interplaylearning.com/basic',desc:'Online and VR simulations for electrical, mechanical, welding and facilities skills.',access:'The vendor’s Basic plan was listed from about US$49 per user per month for small teams in October 2026. Confirm current price, VR support and access from Nigeria.',task:'Complete one electrical or mechanical troubleshooting simulation and compare its isolation steps with M3’s lockout lesson.',deliver:'Completion record and a note on which steps need site-specific authorisation.'},
{name:'Industrial Sims · VR forklift, MEWP and crane',tag:'Commercial VR · quote',path:'L2 · L4 · materials handling and lifting',url:'https://www.industrialsims.com/',desc:'Motion-based VR simulators for forklifts, mobile elevating work platforms (boom and scissor lifts) and cranes, with training and assessment.',access:'Quote-based; book a demo through the provider. Confirm hardware, licence term, assessment exports and support in Nigeria.',task:'In a demo, record the pre-use checks, load limits and exclusion-zone rules the simulator enforces.',deliver:'A pre-use checklist and the limits of what the simulator assessed.'},
{name:'AnyLogic · Personal Learning Edition',tag:'Free desktop simulation',path:'L1 · L5 · logistics',url:'https://www.anylogic.com/downloads/personal-learning-edition-download/',desc:'General-purpose simulation software with material-handling and road-traffic libraries, free for self-study with model-size limits.',access:'Free download for learning; commercial work requires a paid licence.',task:'Model one loading bay with two trucks and a random delay. Compare waiting time with the dispatch lab’s plan.',deliver:'Model screenshot, assumptions table and one recommendation.'},
{name:'DJI · Flight Simulator',tag:'Free tier · desktop',path:'G3 · drone survey',url:'https://www.dji.com/simulator',desc:'DJI’s PC flight simulator; the free version allows general free flight, while paid editions add structured training.',access:'Requires a DJI account and a Windows PC; a compatible controller is recommended.',task:'Fly a simple survey pattern and note how wind settings affect overlap. Link to G3’s no-go conditions.',deliver:'Flight notes and a pre-flight go/no-go checklist.'},
{name:'Simlog · Personal simulators',tag:'Commercial PC simulators · quote',path:'M2 · mobile equipment',url:'https://www.simlog.com/',desc:'PC-based simulators for haul trucks, wheel loaders, excavators and other equipment, used with joysticks and pedals.',access:'Quote-based through Simlog or its resellers. A trade report cited about US$6,000 per commercial licence plus controls; confirm current pricing.',task:'Complete a basic haul-cycle exercise and record every safety violation the simulator flags.',deliver:'Score report and a reflection on which habits would transfer to a real machine.'}
];
function resources(){nav('resources');return `<p class="eyebrow">VERIFIED PROVIDER DIRECTORY</p><h1>Extend your practice.</h1><p class="intro">Start with the labs built into this course. Use the options below for science exploration, specialist software or professionally supervised simulation. Official pages checked 24 October 2026.</p><div class="notice"><strong>Access is clearly labelled.</strong> Online does not always mean free or self-service. Commercial links do not include a licence, partnership or endorsement. Ask the provider to confirm the current access model before purchase.</div><div class="grid two">${providers.map(p=>`<article class="card"><span class="resource-tag">${p.tag}</span><h2 style="margin-top:16px;font-size:1.4rem">${p.name}</h2><span class="pill">${p.path}</span><p style="margin-top:16px">${p.desc}</p><p><strong>Access:</strong> ${p.access}</p><details><summary>Your learning task</summary><div><p>${p.task}</p><p><strong>Keep as evidence:</strong> ${p.deliver}</p></div></details><a href="${p.url}" target="_blank" rel="noopener noreferrer">Open official provider page ↗</a></article>`).join('')}</div><section class="card" style="margin-top:25px"><h2>Before an organisation buys access</h2><p>Request a trial against a named learning outcome. Confirm supported devices, bandwidth and offline behaviour, licence duration, concurrent learners, trainer tools, accessibility, data retention and support in Nigeria. Ask whether assessment evidence can be exported and what the system does not validate.</p><p>For cloud claims, ask the provider to demonstrate the exact learner login and deployment model. Keep a desktop or tabletop alternative for learners who cannot use VR.</p><a class="button light" href="datasets/exploration_targets.csv" download>Download fictional target data ↓</a></section>`;}
function workbook(){nav('workbook');const entries=BASE.modules.filter(m=>state.notes[m.id]||state.quiz[m.id]||state.videoNotes?.[m.id]);return `<p class="eyebrow">YOUR EVIDENCE, IN ONE PLACE</p><h1>My workbook.</h1><p class="intro">Your lesson notes, practice scores, lab records and final-project drafts are saved in this browser. They are not sent to a tutor. Export a backup before changing device, clearing browser data or leaving a shared computer.</p><div class="actions no-print"><button id="export">Export backup (JSON) ↓</button><button id="import" class="light">Import backup ↑</button><button id="download-workbook" class="light">Download readable workbook ↓</button><button id="print" class="light">Print / save PDF</button></div><div class="notice">${storageOK?'Local saving is available.':'Local saving is unavailable. Keep this tab open and export your work now.'} Import replaces the work currently in this browser after confirmation. Keep an export first.</div><div class="section-head"><h2>Lesson records</h2><span class="small muted">${entries.length} started · ${state.completed.length} complete</span></div><div class="workbook-list">${entries.length?entries.map(m=>`<article class="card"><span class="pill">${state.completed.includes(m.id)?'Completed':'In progress'}</span><h3>${m.id} · ${m.title}</h3><p class="small">Practice result: ${state.quiz[m.id]?state.quiz[m.id].score+'/3':'not yet submitted'}</p><p style="white-space:pre-wrap;color:var(--ink)">${esc(state.notes[m.id]||'No activity response recorded yet.')}</p>${state.videoNotes?.[m.id]?`<h4>Viewing notes</h4><p style="white-space:pre-wrap">${esc(state.videoNotes[m.id])}</p>`:''}<a class="no-print" href="#lesson/${m.id}">Continue this lesson →</a></article>`).join(''):'<div class="empty"><h3>Your first entry starts with a lesson.</h3><p>Write your activity response in any lesson and it will appear here.</p><a class="button" href="#lesson/F1">Start F1 →</a></div>'}</div><div class="section-head"><h2>Lab and project records</h2></div><div class="workbook-list">${PATHS.map(p=>`<article class="card"><h3>${p.short}</h3><h4>Lab evidence</h4><p style="white-space:pre-wrap">${esc(state.labs[p.id]||'No lab evidence recorded.')}</p><h4>Final-project draft</h4><p style="white-space:pre-wrap">${esc(state.capstones[p.id]||'No project draft recorded.')}</p><a href="#lab/${p.id}" class="no-print">Open lab →</a> · <a href="#project/${p.id}" class="no-print">Open project →</a></article>`).join('')}</div><details class="no-print"><summary>Shared computer: remove local work</summary><div><p>Export first. This clears only this course’s notes and progress on this browser.</p><button id="clear" class="outline">Clear this browser’s course data</button></div></details>`;}
function assessment(){nav('assessment');return `<p class="eyebrow">BRING THE LEARNING TOGETHER</p><h1>Show your reasoning.</h1><p class="intro">Each final project combines a knowledge task, a practical case, a portfolio and an individual explanation. The browser provides practice and draft storage. A competent assessor must judge practical performance and any course award.</p><div class="grid">${PATHS.map(p=>`<article class="card"><span class="pill">A${PATHS.indexOf(p)} · ${p.short}</span><h3>${p.name}</h3><p>Prepare your evidence, respond to a changed case and explain the limits of your decision.</p><a href="#project/${p.id}">Open project brief →</a></article>`).join('')}</div><section class="card" style="margin-top:25px"><h2>What counts as successful evidence?</h2>${md(BASE.sections.find(s=>s.title==='Assessment and quality assurance system').body)}</section>`;}
function project(id){const p=PATHS.find(p=>p.id===id);if(!p)return notFound();nav('assessment');const sec=BASE.sections.find(s=>s.title.startsWith('A'+PATHS.indexOf(p)+' '));if(!sec)return lockedPage('project',id);const body=sec.body;const parts=body.split('### ');const knowledge=parts.find(x=>x.startsWith('Knowledge paper and key'))||'';const qs=knowledge.split('\n').slice(1).filter(l=>/^\d\./.test(l)).map(l=>{const [q,key]=l.split('**4 marks:**');return {q:q.replace(/^\d\. /,''),key};});const other=parts.filter(x=>!x.startsWith('Knowledge paper and key'));return `<a href="#assessment" class="small">← All final projects</a><p class="eyebrow" style="margin-top:20px">A${PATHS.indexOf(p)} / ${p.short}</p><h1 class="lesson-title">${p.name}: final project</h1><div class="notice">This is an open practice brief. Model guidance is available below. A formal assessment needs a changed case, observed practical work and an individual assessor decision; the website does not issue a competence certificate.</div><section class="card"><h2>Part 1 · Explain what you know</h2><p>Answer individually in your project draft before opening the guidance.</p><ol>${qs.map(q=>`<li>${inline(q.q)}</li>`).join('')}</ol><details><summary>Practice marking guidance</summary><div>${qs.map((q,i)=>`<p><strong>${i+1}.</strong> ${inline(q.key||'Refer to the assessor criteria.')}</p>`).join('')}</div></details></section><section class="card" style="margin-top:22px"><h2>Parts 2–4 · Perform, record and explain</h2>${md(other.join('\n### '))}<div class="actions"><a class="button" href="#lab/${id}">Open the supporting lab →</a></div></section><section class="card workbook" style="margin-top:22px"><h2>Your project draft</h2><label for="project-notes">Knowledge answers, practical evidence and oral preparation</label><textarea id="project-notes" data-path="${id}" style="min-height:300px" placeholder="1. Knowledge answers…\n2. Practical case: method, results, controls and limitations…\n3. Evidence portfolio: records and calculations…\n4. Oral defence: explain a changed case and your authority limits…">${esc(state.capstones[id]||'')}</textarea><p class="small muted">Autosaved locally. Export your workbook to share through your provider’s agreed process. Do not enter real sensitive workplace information.</p><a href="#workbook">Review and export my evidence →</a></section>`;}
function guide(){nav('guide');return `<p class="eyebrow">A COURSE YOU CAN WORK THROUGH</p><h1>Your learning guide.</h1><div class="grid two"><section class="card"><h2>Start with the foundation</h2><p>Work through F1–F5. Then choose exploration, operations, processing, logistics, or environment and community. Each specialist route contains five modules, a practice lab, a facilitated case and a final project.</p><p>The full programme design is 60 guided foundation hours plus a 180-hour specialist route. These include instructor demonstrations, repeated practice and assessment. This website supplies the self-study content and practice tools; it does not claim that clicking through pages completes 240 hours of training.</p></section><section class="card"><h2>Use the learning cycle</h2><ol><li>Read the plain-English explanation and vocabulary.</li><li>Watch the topic video and complete its viewing task, or use the written alternative.</li><li>Follow the worked example, then use the tutor or study tools to explain it from memory.</li><li>Complete the activity in your own workbook.</li><li>Try the related lab with two different conditions.</li><li>Answer all three knowledge questions and use the feedback.</li><li>Record completion and revisit the topic in the final project.</li></ol></section></div><section class="card" style="margin-top:22px"><h2>Support and study habits</h2><p>Use a calculator for arithmetic, enlarge the page if useful and discuss unfamiliar terms with a trainer. Explain ideas aloud in a familiar language, then check the technical meaning in English. Work in short study blocks and revisit an earlier question at the start of the next session. All labs can be used without a VR headset.</p><h3>A short readiness check</h3><p>Calculate 15% of 200; convert 2.5 tonnes to kilograms; identify the larger of 0.8% and 0.08%; save and reopen a file; explain why a damaged guard requires a hold.</p><details><summary>Check your readiness answers</summary><div><p>30; 2,500 kg; 0.8%; a file you can retrieve; pause and report the affected task rather than approach or repair without authority. If these are difficult, use a supported numeracy and digital-skills bridge before specialist work.</p></div></details><h3>Use your topic tutor</h3><p>Solve the core task first. If an approved AI tool is available, use only fictional data and ask it to critique your reasoning. Check every number and source. Keep a short record: suggestion → accepted, changed or rejected → reason. Each topic has prepared study tools and an Azure AI tutor panel. Live AI is available to signed-in, enrolled learners. The tutor sends only the question and recent conversation when you explicitly ask; it does not automatically attach workbook notes. Use the panel’s connection status to see availability.</p><div class="worked"><p><strong>Practice prompt:</strong> “Use only this fictional table. Identify missing units and inconsistencies. Cite row IDs. Separate observations from hypotheses. Do not invent values or recommend equipment-control changes. Ask me one question that tests my reasoning.”</p></div></section><section class="card" style="margin-top:22px"><h2>Downloads and access</h2><p>Download the portable course to use in a browser without a network connection. Extract the ZIP and open index.html. External provider links need the internet. Browser storage behaviour can vary for local files, so always export your workbook backup.</p><a class="button" href="mining-course-offline.zip" download>Download the complete offline course ↓</a><div class="actions"><a href="datasets/exploration_targets.csv" download>Exploration CSV</a><a href="datasets/environment_readings.csv" download>Environment CSV</a><a href="datasets/telemetry.csv" download>Telemetry CSV</a></div><p class="source" style="margin-top:16px">The hosted review site may require its owner’s access. Your notes and progress are saved in this browser; export a backup regularly.</p></section><section class="card" style="margin-top:22px"><h2>For the course provider</h2><details><summary>The AI tutor</summary><div><p>Enrolled learners can ask the Azure AI tutor about each module after signing in. It explains, gives worked examples, hints and practice questions, and checks reasoning. It does not mark work, issue certificates or authorise real tasks, and it applies fair-use limits per learner.</p></div></details><p>Use the practical case packs and final projects with qualified specialists. Validate technical content against the actual site, equipment, applicable requirements and intended award. Add supervised workplace observations before making occupational competence claims. Browser practice scores are formative only.</p><details><summary>Delivery schedule and learner support</summary><div>${md(BASE.sections.find(s=>s.title==='Foundation delivery schedule').body)}${md(BASE.sections.find(s=>s.title==='Admission and learner support').body)}</div></details><details><summary>Facilities, certification and quality improvement</summary><div>${['Facilities and simulator procurement','Accreditation staffing and workplace progression','Launch and continuous improvement','Workforce capacity and commercial planning'].map(t=>`<h3>${t}</h3>${md(BASE.sections.find(s=>s.title===t).body)}`).join('')}</div></details></section><section class="card" style="margin-top:22px"><h2>Sources and technical boundaries</h2><p>The learning explanations, questions and browser models are original course material. Official sources support technical checks and further reading; source inclusion does not imply endorsement or accreditation. Fictional exercise limits are not real operating or legal limits.</p><ul class="source-list">${sourceLinks.map(([n,u])=>`<li><a href="${u}" target="_blank" rel="noopener noreferrer">${n} ↗</a></li>`).join('')}</ul><details><summary>Full source notes and original plan corrections</summary><div>${md(BASE.sections.find(s=>s.title==='Evidence corrections and design decisions').body)}${BASE.sections.filter(s=>s.title.startsWith('Source register')).map(s=>md(s.body)).join('')}</div></details></section>`;}
const sourceLinks=[['Nigerian Ministry of Solid Minerals Development · official documents','https://msmd.gov.ng/downloads/'],['NBTE · National Skills Qualifications','https://www.web.nbte.gov.ng/nsq'],['IFC · Environmental, Health and Safety Guidelines for Mining','https://www.ifc.org/content/dam/ifc/doc/2000/2007-mining-ehs-guidelines-en.pdf'],['IFC · General Environmental, Health and Safety Guidelines','https://www.ifc.org/en/insights-reports/general-environmental-health-and-safety-guidelines'],['QGIS · official training manual','https://docs.qgis.org/3.44/en/docs/training_manual/'],['NCAA · remotely piloted aircraft requirements','https://ncaa.gov.ng/media/l2vjnlce/nig-cars-part-21-remotely-piloted-aircraft-system.pdf'],['NDPC · Nigeria Data Protection Act 2023','https://ndpc.gov.ng/wp-content/uploads/2024/03/Nigeria_Data_Protection_Act_2023.pdf'],['Thermo Fisher · handheld XRF and lithium limitations','https://documents.thermofisher.com/TFS-Assets/CAD/Application-Notes/lithium-ion-battery-recycling-handheld-xrf-analysis-an1120-en.pdf'],['OECD · responsible mineral supply-chain due diligence','https://www.oecd.org/en/publications/oecd-due-diligence-guidance-for-responsible-supply-chains-of-minerals-from-conflict-affected-and-high-risk-areas_9789264252479-en.html']];
function notFound(){return '<h1>Page not found.</h1><p>Choose a course pathway to continue.</p><a href="#courses">Open course pathways →</a>';}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportState(){download('mining-learning-backup.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Backup exported. Keep it somewhere you can find again.');}
function readableWorkbook(){let html='<h1>Mining Skills Learning Workbook</h1><p>Self-study evidence export · '+new Date().toLocaleDateString('en-GB')+'</p><p>Practice results are not an assessed qualification.</p>';for(const m of BASE.modules){if(state.notes[m.id]||state.quiz[m.id]||state.videoNotes?.[m.id])html+=`<section><h2>${m.id} · ${esc(m.title)}</h2><p>Practice: ${state.quiz[m.id]?.score??'Not submitted'}${state.quiz[m.id]?'/3':''} · ${state.completed.includes(m.id)?'Learning complete':'In progress'}</p><pre>${esc(state.notes[m.id]||'No activity response.')}</pre>${state.videoNotes?.[m.id]?`<h3>Viewing notes</h3><pre>${esc(state.videoNotes[m.id])}</pre>`:''}</section>`;}for(const p of PATHS)if(state.labs[p.id]||state.capstones[p.id])html+=`<section><h2>${p.short} evidence</h2><h3>Lab</h3><pre>${esc(state.labs[p.id]||'No record')}</pre><h3>Project draft</h3><pre>${esc(state.capstones[p.id]||'No draft')}</pre></section>`;download('mining-learning-workbook.html','<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My mining workbook</title><style>body{font:16px/1.7 system-ui;max-width:850px;margin:40px auto;padding:20px;color:#19362e}pre{font:inherit;white-space:pre-wrap}section{border-top:1px solid #ddd;margin-top:30px}h1,h2{line-height:1.3}@media print{section{break-inside:avoid}}</style>'+html+'</html>','text/html');}
function bindPage(type,id){document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'});});const notes=document.getElementById('notes');if(notes)notes.oninput=()=>{state.notes[id]=notes.value;if(notes.value.trim().length<80)state.completed=state.completed.filter(x=>x!==id);document.getElementById('note-count').textContent=notes.value.length+' characters · autosaved as you type';save();};const q=document.getElementById('quiz');if(q)q.onsubmit=e=>{e.preventDefault();const a=LESSONS[id].quiz.map((_,i)=>Number(new FormData(q).get('q'+i))),score=a.reduce((n,v,i)=>n+(v===LESSONS[id].quiz[i][2]),0);state.quiz[id]={answers:a,score};if(score<3)state.completed=state.completed.filter(x=>x!==id);save();LESSONS[id].quiz.forEach((item,i)=>{const correct=a[i]===item[2],el=document.getElementById('qfb'+i);el.className='feedback'+(correct?'':' bad');el.textContent=(correct?'Correct. ':'Review this. ')+item[3];});document.getElementById('quiz-result').textContent=`${score}/3 correct. ${score===3?'Now check that your activity response explains your own reasoning.':'Read the feedback, return to the relevant section and retry.'}`;};const complete=document.getElementById('complete');if(complete)complete.onclick=()=>{if(state.quiz[id]?.score!==3){toast('Answer all three practice questions correctly first.');document.getElementById('check').scrollIntoView({behavior:'smooth'});return;}if((state.notes[id]||'').trim().length<80){toast('Record your own activity response: at least 80 characters.');notes.focus();return;}if(!state.completed.includes(id))state.completed.push(id);save();complete.textContent='✓ Module completed';toast('Learning milestone saved. Practical competence still needs assessment.');};const ln=document.getElementById('lab-notes');if(ln)ln.oninput=()=>{state.labs[id]=ln.value;save();};const cap=document.getElementById('capture-lab');if(cap)cap.onclick=()=>{let record=currentLabResult;if(id==='M')record=`Safe-shift run ${ops.variant+1}: ${ops.done?'completed':ops.failed?'ended for a critical choice':'in progress'}.\n`+ops.log.join('\n');if(id==='P')record+='\n'+document.getElementById('tank-output').dataset.result+'\nQC: '+(document.getElementById('qc-output').textContent||'Not yet reviewed.');if(!record){toast('Make a decision or run the calculation first.');return;}state.labs[id]=(state.labs[id]||'')+'\n\n'+record;ln.value=state.labs[id];save();toast('Result added. Add your own explanation beneath it.');};const pn=document.getElementById('project-notes');if(pn)pn.oninput=()=>{state.capstones[id]=pn.value;save();};const search=document.getElementById('search');if(search)search.oninput=()=>{const term=search.value.toLowerCase().trim(),found=BASE.modules.filter(m=>(m.title+' '+LESSONS[m.id].simple.flat().join(' ')).toLowerCase().includes(term));document.getElementById('path-cards').style.display=term?'none':'';document.getElementById('search-results').innerHTML=term?`<p class="small muted">${found.length} matching modules</p><div class="module-list">${found.map(m=>`<a class="module-row" href="#lesson/${m.id}"><span class="module-code">${m.id}</span><div><h3>${m.title}</h3><p>${LESSONS[m.id].hook}</p></div></a>`).join('')}</div>`:'';};if(type==='lab'&&!document.getElementById('locked'))setupLab(id);const buttons={export:exportState,import:()=>document.getElementById('import-file').click(),'download-workbook':readableWorkbook,print:()=>window.print(),clear:()=>{if(confirm('Clear this course’s notes and progress on this browser? Export first if you want to keep them.')){state={version:1,notes:{},videoNotes:{},quiz:{},completed:[],labs:{},capstones:{},last:'F1'};save();render();}}};Object.entries(buttons).forEach(([k,fn])=>{const b=document.getElementById(k);if(b)b.onclick=fn;});}
function render(){const route=(location.hash.slice(1)||'landing').split('/'),type=route[0],id=route[1];document.body.classList.toggle('landing-mode',type==='landing');const f={landing,home,courses,path:()=>pathPage(id),lesson:()=>lesson(id),labs,lab:()=>labPage(id),resources,videos:videoLibrary,workbook,assessment,project:()=>project(id),guide,account:accountPage,nigeria:()=>extraPage('nigeria'),career:()=>extraPage('career'),simplan:simPlanPage}[type];document.getElementById('main').innerHTML=f?f():notFound();bindPage(type,id);bindLearningSupport(type,id);if(type==='landing')bindLanding();updateProgress();document.body.classList.remove('menu-open');document.getElementById('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);document.title=(type==='lesson'&&LESSONS[id]?id+' · '+BASE.modules.find(m=>m.id===id).title:'Mining Skills Learning Lab');}
document.getElementById('menu').onclick=()=>{document.body.classList.toggle('menu-open');document.getElementById('menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));};document.getElementById('export-side').onclick=exportState;
document.getElementById('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('File is too large. Choose a course backup smaller than 2 MB.');const data=JSON.parse(await file.text());if(data.version!==1||!data.notes||!data.quiz||!Array.isArray(data.completed))throw Error('This is not a supported course backup.');const clean=validateState(data);if(confirm('Replace the current browser workbook with this backup? Export your current work first if needed.')){state=clean;save();render();toast('Backup imported.');}}catch(err){toast('Import failed: '+err.message);}e.target.value='';};
document.querySelector('.skip').onclick=e=>{e.preventDefault();document.getElementById('main').focus();};
window.addEventListener('hashchange',render);render();
